-- Generated by svetra from svetra.yaml (copy of supabase/schemas/svetra.sql), plus the guard trigger below.

-- Tables
create table "public"."doc" (
  "id" uuid primary key default gen_random_uuid(),
  "author" uuid not null,
  "reviewer" uuid not null,
  "title" text not null,
  "status" text not null default 'draft',
  constraint "doc_status_values" check ("status" in ('draft', 'submitted', 'approved', 'rejected'))
);

-- Foreign keys
alter table "public"."doc" add constraint "doc_author_fkey" foreign key ("author") references "auth"."users" ("id");
alter table "public"."doc" add constraint "doc_reviewer_fkey" foreign key ("reviewer") references "auth"."users" ("id");

-- Indexes
create index "doc_author_idx" on "public"."doc" ("author");
create index "doc_reviewer_idx" on "public"."doc" ("reviewer");

-- Access
alter table "public"."doc" enable row level security;

-- Policies
create policy "author_sees_own" on "public"."doc"
  for select to authenticated
  using ("author" = (select auth.uid()));

create policy "reviewer_sees_submitted" on "public"."doc"
  for select to authenticated
  using ("reviewer" = (select auth.uid()) and "status" <> 'draft');

create policy "author_creates_draft" on "public"."doc"
  for insert to authenticated
  with check ("author" = (select auth.uid()) and "reviewer" <> (select auth.uid()) and "status" = 'draft');

create policy "author_edits_draft" on "public"."doc"
  for update to authenticated
  using ("author" = (select auth.uid()) and "status" = 'draft')
  with check ("author" = (select auth.uid()) and "reviewer" <> (select auth.uid()) and "status" in ('draft', 'submitted'));

create policy "author_deletes_draft" on "public"."doc"
  for delete to authenticated
  using ("author" = (select auth.uid()) and "status" = 'draft');

create policy "reviewer_decides" on "public"."doc"
  for update to authenticated
  using ("reviewer" = (select auth.uid()) and "author" <> (select auth.uid()) and "status" = 'submitted')
  with check ("reviewer" = (select auth.uid()) and "author" <> (select auth.uid()) and "status" in ('approved', 'rejected'));

-- Column rules that row-level policies cannot express (they only see the new row):
-- author and reviewer never change; the title changes only while the document is a draft;
-- status only moves draft -> submitted -> approved or rejected.
create function "public"."doc_guard_update"() returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.id is distinct from old.id
     or new.author is distinct from old.author
     or new.reviewer is distinct from old.reviewer then
    raise exception 'author and reviewer of a document cannot change' using errcode = '42501';
  end if;
  if new.title is distinct from old.title and old.status <> 'draft' then
    raise exception 'only a draft can be retitled' using errcode = '42501';
  end if;
  if new.status is distinct from old.status
     and not ((old.status = 'draft' and new.status = 'submitted')
           or (old.status = 'submitted' and new.status in ('approved', 'rejected'))) then
    raise exception 'invalid status change from % to %', old.status, new.status using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger "doc_guard_update" before update on "public"."doc"
  for each row execute function "public"."doc_guard_update"();
